code:
def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited
    supply of each coin in *coins*. Return -1 if impossible.
    Standard DP solution with O(amount * len(coins)) time.
    """
    if amount < 0:
        return -1
    # dp[i] = min coins to make i; initialize large sentinel
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

