def solve(line: str):
    """Parse a single CSV line according to simple quoting rules.
    Fields are separated by commas. Fields may be optionally enclosed in double quotes.
    Inside quoted fields, a pair of double quotes "" represents a literal quote character.
    The function returns a list of field strings.
    """
    fields = []
    field_chars = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Look ahead for escaped quote
                if i + 1 < n and line[i + 1] == '"':
                    field_chars.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field_chars.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(field_chars))
                field_chars = []
            elif ch == '"':
                in_quotes = True
            else:
                field_chars.append(ch)
        i += 1
    # Append the last field (handles empty line as [''])
    fields.append(''.join(field_chars))
    return fields

