def solve(n):
    if n <= 2:
        return 0
    sieve = bytearray(b'\x01') * n
    sieve[0:2] = b'\x00\x00'
    import math
    limit = int(math.isqrt(n - 1))
    count = 0
    for i in range(2, n):
        if sieve[i]:
            count += 1
            if i <= limit:
                step = i
                start = i * i
                sieve[start:n:step] = b'\x00' * ((n - start - 1)//step + 1)
    return count

