def solve(nums):
    """Return the length of the longest strictly increasing subsequence of *nums*.
    Uses the classic patience‑sorting / binary‑search algorithm with O(n log n)
    time and O(n) space.
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find position to replace (first element >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

