    def neighbors(r, c):
        # up
        if r-1 >= 0 and c < len(grid[r-1]):
            yield r-1, c
        # down
        if r+1 < rows and c < len(grid[r+1]):
            yield r+1, c
        # left
        if c-1 >= 0:
            yield r, c-1
        # right
        if c+1 < len(grid[r]):
            yield r, c+1
    def bfs(start_r, start_c):
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            if grid[r][c] != 1:
                continue
            visited.add((r, c))
            for nr, nc in neighbors(r, c):
