def solve(grid):
    """Count islands of 1s in a binary grid.
    Cells are connected 4-directionally. Handles empty grid and ragged rows.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Determine max columns for ragged handling
    max_cols = max((len(row) for row in grid), default=0)
    visited = [[False]*len(row) for row in grid]
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # explore neighbours
            for di,dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and not visited[ni][nj] and grid[ni][nj]==1:
                    stack.append((ni,nj))
    count=0
    for i,row in enumerate(grid):
        for j,val in enumerate(row):
            if val==1 and not visited[i][j]:
                dfs(i,j)
                count+=1
    return count

